using System;using System.IO;using Serilog;namespace SAUDICO.Federate.Logging;public static class LoggingBootstrapper{public static void Start(){var d=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"SAUDICO","Federate","logs");Directory.CreateDirectory(d);Log.Logger=new LoggerConfiguration().MinimumLevel.Information().WriteTo.File(Path.Combine(d,"federate-.log"),rollingInterval:RollingInterval.Day,retainedFileCountLimit:30).CreateLogger();}public static void Stop()=>Log.CloseAndFlush();}